// SignOrderBulkOrders signs order.bulk_orders in place: every element of orders on its own, with its own nonce and expiration. Each order is signed on its own, like create_order: OrderWithBuilderFee when that order's builder is set to a non-zero address, otherwise Order. The cancel lists and time_to_live_ms are not signed.
func SignOrderBulkOrders(ctx context.Context, rt *Runtime, req *models.ApiBulkOrdersRequestInput) error {
	type pendingSig struct {
		sig *models.SignatureInput
		st  *StructType
		msg Value
	}
	pending := make([]pendingSig, 0, len(req.Orders))
	for i := range req.Orders {
		view := models.ApiCreateOrderRequestInput{Order: req.Orders[i]}
		sig, st, msg, err := func(req *models.ApiCreateOrderRequestInput) (*models.SignatureInput, *StructType, Value, error) {
			if req.Order.Signature == nil {
				req.Order.Signature = &models.SignatureInput{}
			}
			sig := req.Order.Signature
			if err := rt.PrepareSignature(&sig.Signer, &sig.Nonce, &sig.Expiration, &sig.ChainID, SignatureTTL); err != nil {
				return nil, nil, nil, err
			}
			var instruments, currencies []string
			for _, e := range req.Order.Legs {
				instruments = append(instruments, e.Instrument)
			}
			meta, err := loadMetadata(ctx, rt, instruments, currencies, false)
			if err != nil {
				return nil, nil, nil, err
			}
			if rt.checkOrders {
				if err := CheckOrder(&orderChecks, req.Order, meta); err != nil {
					return nil, nil, nil, err
				}
			}
			b := &MessageBuilder{}
			var st *StructType
			var msg Value
			if AddressSet(req.Order.Builder) {
				st, msg = eip712OrderWithBuilderFee, messageOrderWithBuilderFee(b, req, meta)
			} else {
				st, msg = eip712Order, messageOrder(b, req, meta)
			}
			if b.Err != nil {
				return nil, nil, nil, b.Err
			}
			return sig, st, msg, nil
		}(&view)
		req.Orders[i] = view.Order
		if err != nil {
			return err
		}
		pending = append(pending, pendingSig{sig, st, msg})
	}
	for _, p := range pending {
		s, err := rt.Sign(ctx, p.sig.ChainID, p.st, p.msg)
		if err != nil {
			return err
		}
		p.sig.Signer, p.sig.R, p.sig.S, p.sig.V = s.Signer, s.R, s.S, &s.V
	}
	return nil
}

