// SignTransferTransfer signs transfer.transfer in place. If from_wallet_type and to_wallet_type are both set: TransferV2 when the currency id fits uint8 (<= 255), else TransferV3. If neither is set: Transfer (only for currency ids <= 255). Setting only one...
func SignTransferTransfer(ctx context.Context, rt *Runtime, req *models.ApiTransferRequestInput) error {
	if req.Signature == nil {
		req.Signature = &models.SignatureInput{}
	}
	sig := req.Signature
	if err := rt.PrepareSignature(&sig.Signer, &sig.Nonce, &sig.Expiration, &sig.ChainID, SignatureTTL); err != nil {
		return err
	}
	var instruments, currencies []string
	currencies = append(currencies, req.Currency)
	meta, err := loadMetadata(ctx, rt, instruments, currencies, false)
	if err != nil {
		return err
	}
	b := &MessageBuilder{}
	var st *StructType
	var msg Value
	c, err := meta.Currency(req.Currency)
	if err != nil {
		return err
	}
	fromUnset, toUnset := req.FromWalletType == "", req.ToWalletType == ""
	switch {
	case fromUnset != toUnset:
		return &SigningError{Message: "set both from_wallet_type and to_wallet_type, or neither"}
	case fromUnset && c.ID > 255:
		return &SigningError{Message: fmt.Sprintf("currency id %d needs from_wallet_type and to_wallet_type", c.ID)}
	case fromUnset:
		st, msg = eip712Transfer, messageTransfer(b, req, meta)
	case c.ID <= 255:
		st, msg = eip712TransferV2, messageTransferV2(b, req, meta)
	default:
		st, msg = eip712TransferV3, messageTransferV3(b, req, meta)
	}
	if b.Err != nil {
		return b.Err
	}
	s, err := rt.Sign(ctx, sig.ChainID, st, msg)
	if err != nil {
		return err
	}
	sig.Signer, sig.R, sig.S, sig.V = s.Signer, s.R, s.S, &s.V
	return nil
}

// SignTransferWithdrawal signs transfer.withdrawal in place. Withdrawal when the currency id fits uint8 (<= 255), else WithdrawalV2.
